/* 中文词库 · 给「英语母语、学中文」那一档用的（2026-09-23 加，见 CLAUDE.md「多语言」那一节）
   来源：HSK 3.0（2021 版）1~6 级词表（complete-hsk-vocabulary，MIT），只收实词，
   英文释义是**逐条手写的最常用义**（字典第一义常常是冷门义，比如「药」第一条是「鸢尾叶」）。
   另外为了让每一档都有动物 / 颜色这两类，给低档补了几个 HSK 里排得靠后的基础词（猫、狗、红色…）。

   格式：[汉字, 英文释义, 类别, 难度, 词性, 拼音]   难度 1~6 = HSK 1~6
   ⚠️ 这张表跟英语词库（words-a1.js）**共用同一套全局变量**：
      学中文时下面那段会把 WORDS / WMAP / BYCAT / BYPOS / BYLV / ALLW 整套换成这一份。
      词对象的字段名还是 en / cn —— **en 是「要学的那个词」（这里是汉字），cn 是「母语释义」（这里是英文）**，
      多一个 py（拼音）。game.js 一个字段名都不用改。
   ⚠️ 跟英语词库一样的规矩：**只许往数组末尾追加**（存档码按下标存熟练度），
      汉字不能重复，同一难度里英文释义不能重复（选择题的干扰项在同难度里挑）。
      汉字最长 4 个（拼字题的字格）。*/
